/**
 * Retrieves the summary of a single inbox thread. Use the list thread emails endpoint to retrieve the messages that make up the thread.
 *
 * Returns the thread summary. The emails in the thread are listed with the list thread emails endpoint.
 *
 * @param inboxId - The Inbox ID. An email address is not accepted.
 * @param threadId - The Thread ID.
 */
export async function inboxesGetThread(
  config: ClientConfig,
  { inboxId, threadId }: InboxesGetThreadParams,
  requestOptions?: RequestOptions,
): Promise<InboxThreadSummary> {
  validateUuid("inbox_id", inboxId);

  validateUuid("thread_id", threadId);

  const _resp = await sdkRequest<InboxThreadSummary>({
    method: "GET",
    path: `/inboxes/${encodePathSegment(inboxId)}/threads/${encodePathSegment(threadId)}`,
    operationId: "inboxesGetThread",
    responseDecoder: "json",
    ...requestOptions,
    config,
  });
  return sdkDecode(_resp, () => decodeResponseEnums(_resp.data, { ref: "InboxThreadSummary" }));
}
